package com.aoo.bcg.gamespi.fsm;
import java.util.List;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class UndeclaredTransitionSideEffectTest{enum Event{OPEN,ILLEGAL}@Test void undeclaredAndGuardRejectedEventsHaveZeroSideEffects(){var table=new StateTransitionTable<RoomLifecycleState,Event>(List.of(new StateTransition<>(RoomLifecycleState.CREATED,Event.OPEN,RoomLifecycleState.WAITING,"configured","publish")));var effects=new AtomicInteger();var missing=table.tryTransition(RoomLifecycleState.CREATED,Event.ILLEGAL,name->true,name->effects.incrementAndGet());assertFalse(missing.accepted());assertEquals(RoomLifecycleState.CREATED,missing.state());var guarded=table.tryTransition(RoomLifecycleState.CREATED,Event.OPEN,name->false,name->effects.incrementAndGet());assertFalse(guarded.accepted());assertEquals(0,effects.get());}}
